const files = $input.all().map(i => i.json).flat();

const PII_PATTERNS = [
  'sin_encrypted', 'birth_date', 'gender', 'medical',
  'prescription', 'annual_income', 'total_assets',
  'total_liabilities', 'net_worth', 'drivers_license',
  'is_smoker', 'marital_status', 'canadian_status',
  'has_existing_policies'
];

const SENSITIVE_FILE_PATTERNS = [
  /medical/, /prescription/, /partner/, /res_partner/
];

const sensitiveFiles = [];
let combinedPatch = '';

for (const f of files) {
  const fname = f.filename || '';
  const patch = f.patch || '';

  const isSensitiveFile = SENSITIVE_FILE_PATTERNS.some(p => p.test(fname));
  const hasPiiField = PII_PATTERNS.some(p => patch.includes(p));

  if (isSensitiveFile || hasPiiField) {
    sensitiveFiles.push({ file: fname, reason: isSensitiveFile ? 'sensitive_model' : 'pii_field' });
    combinedPatch += `\n--- ${fname} ---\n${patch.substring(0, 3000)}\n`;
  }
}

if (sensitiveFiles.length === 0) {
  return [{ json: { skip: true } }];
}

return [{
  json: {
    skip: false,
    sensitiveFiles,
    patch: combinedPatch.substring(0, 10000),
    prNumber: $('PR Webhook').item.json.body.number,
    repoFullName: $('PR Webhook').item.json.body.repository.full_name
  }
}];

const review = $json.response || 'Compliance check did not return a response.';
const ctx = $('Detect PII Changes').item.json;

let body = `## 🛡️ PIPEDA Compliance Scan\n\n`;
body += `**Files with PII/sensitive data changes:** ${ctx.sensitiveFiles.length}\n\n`;

for (const f of ctx.sensitiveFiles) {
  body += `- \`${f.file}\` — ${f.reason === 'sensitive_model' ? 'Sensitive model file' : 'Contains PII field references'}\n`;
}

body += `\n### Compliance Analysis\n\n${review}\n\n`;
body += `---\n*Auto-generated PIPEDA compliance scan by n8n + Ollama*`;

return [{ json: { body, prNumber: ctx.prNumber, repoFullName: ctx.repoFullName } }];
